    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    names = data[1:]

    # Create a graph to represent the order of characters
    graph = {chr(i): [] for i in range(ord('a'), ord('z') + 1)}
    in_degree = {chr(i): 0 for i in range(ord('a'), ord('z') + 1)}

    for i in range(n - 1):
        name1 = names[i]
        name2 = names[i + 1]
        min_len = min(len(name1), len(name2))

        for j in range(min_len):
            if name1[j] != name2[j]:
                if name2[j] not in graph[name1[j]]:
                    graph[name1[j]].append(name2[j])
                    in_degree[name2[j]] += 1
                break
        else:
            if len(name1) > len(name2):
                print("Impossible")
                return

    # Perform topological sort
    queue = [chr(i) for i in range(ord('a'), ord('z') + 1) if in_degree[chr(i)] == 0]
    result = []

    while queue:
        node = queue.pop(0)
        result.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) == 26:
        print(''.join(result))
    else:
        print("Impossible")

